<pre>
String eid = request.getParameter("eid");
...
ServletOutputStream out = response.getOutputStream();
out.print("Employee ID: " + eid);
...
out.close();
...
</pre>
</ConditionalText>
<ConditionalText condition="trace:java.sun.com/jsp/jstl">
