<pre>
Employee ID: &lt;c:out value="${param.eid}" escapeXml="false"/&gt;
</pre>
</ConditionalText>
<ConditionalText condition="trace:java.sun.com/jsf trace:myfaces.apache.org/trinidad trace:myfaces.apache.org/tomahawk">
