   ...
   &lt;h:dataTable value="employeesBean.employeeList" var="employee"&gt;
      ...
      &lt;h:column&gt;
         &lt;f:facet name="header"&gt;
            &lt;h:outputText value="Employee Name"/&gt;
         &lt;/f:facet&gt;
         &lt;h:outputText value="#{employee.name}" escape="false"/&gt;
      &lt;/h:column&gt;
      ...
   &lt;/h:dataTable&gt;
   ...
&lt;/f:view&gt;
</pre>
</ConditionalText>
